local function add(ctx,self)local p=ctx:controller(self);ctx:grant_player_keyword(p,"cthun_buffs");ctx:increment_player_data(p,"cthun_attack_buff",2);ctx:increment_player_data(p,"cthun_health_buff",2)end
return {api_version=1,id="OG_162",name="Disciple of C'Thun",text="<b>Battlecry:</b> Deal 2 damage. Give your C'Thun +2/+2 <i>(wherever it is)</i>.",set="OG",type="minion",rarity="rare",cost=3,attack=2,health=2,keywords={"battlecry"},target_mode="required_if_available",targets=function(ctx)return ctx:characters()end,on_battlecry=function(ctx,self,target)if target then cardlib.effects.damage(ctx, target,2)end;add(ctx,self)end}
